export default function Icon({ name, size = 32, color = '#61666B', className }: IconProps) {
  const src = useMemo(() => {
    const cfg = ICONS[name]
    if (!cfg) return ''
    const svg = cfg.fill
      ? `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${cfg.vb}"><g fill="${color}">${cfg.body}</g></svg>`
      : `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${cfg.vb}" fill="none"><g stroke="${color}" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">${cfg.body}</g></svg>`
    return 'data:image/svg+xml,' + encodeURIComponent(svg)
  }, [name, color])

  // Taro H5 端 inline style 不支持 rpx，运行时按屏幕宽度换算为 px（小程序端同样适用）
  const sizePx = useMemo(() => {
    try {
      return (Taro.getSystemInfoSync().windowWidth / 750) * size
    } catch {
      return size * 0.5
    }
  }, [size])

  return (
    <View className={className} style={{ width: `${sizePx}px`, height: `${sizePx}px`, flexShrink: 0 }}>
      <Image className='icon-img' src={src} mode='aspectFit' />
    </View>
  )
}
